// Проверка подписи входящего вебхука и разбор сообщения.
//
// Без этой проверки вебхук открыт: кто узнал адрес, тот может прислать
// {phone, text} от имени любого водителя — и отметить этап чужого рейса.
// Платформа доверяет нашей подписи; мы обязаны доверять только провайдеру.
//
// Meta (WhatsApp Cloud API) подписывает тело так же, как RAHTIS:
// HMAC-SHA256 на App Secret, заголовок X-Hub-Signature-256 вида sha256=<hex>.
// Если провайдер другой — замените проверку на его схему, но не убирайте.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.WHATSAPP_APP_SECRET) SECRET = $vars.WHATSAPP_APP_SECRET; } catch (e) {}
if (!SECRET) throw new Error('WHATSAPP_APP_SECRET ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v SECRET.');
const secret = SECRET;

// rawBody включён в узле Webhook: подпись обязана считаться от тех же
// байтов, которые прислал провайдер. Пересобранный JSON даст другую строку.
const raw = $json.body === undefined ? '' : (typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body));
const given = $json.headers['x-hub-signature-256'] || '';

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');

// Сравнение постоянного времени: обычное === выходит на первом несовпавшем
// байте, и подпись подбирается побайтово по времени ответа.
const a = Buffer.from(expected);
const b = Buffer.from(given);
const ok = a.length === b.length && crypto.timingSafeEqual(a, b);

let payload = {};
try { payload = typeof raw === 'string' && raw ? JSON.parse(raw) : ($json.body || {}); } catch (e) { payload = {}; }

// Разбор формата WhatsApp Cloud API. Запасные пути — для ручной проверки
// из curl и для провайдеров с плоским телом.
const msg = payload?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const phoneRaw = msg?.from || payload.phone || payload.from || '';
const text = msg?.text?.body || payload.text || payload.message || '';

// Только цифры — ровно так же нормализует база (app.phone_digits).
const phone = String(phoneRaw).replace(/\D/g, '');

return [{ json: { ok, phone, text } }];

// Подпись запроса к RAHTIS.
//
// Проверено на боевом эндпоинте: HMAC-SHA256 на DRIVER_WEBHOOK_SECRET от
// строки `${timestamp}.${body}`, заголовок x-rahtis-signature вида
// sha256=<hex>, окно 300 секунд.
//
// Тело уходит как raw: если дать узлу HTTP пересобрать JSON, подпись
// начнёт зависеть от порядка ключей и разойдётся с нашей.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.DRIVER_WEBHOOK_SECRET) SECRET = $vars.DRIVER_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('DRIVER_WEBHOOK_SECRET ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v SECRET.');
const secret = SECRET;

const body = JSON.stringify({ phone: $json.phone });
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');

return [{ json: { body, timestamp, signature, phone: $json.phone, text: $json.text } }];

// Запрос к Claude: понять водителя и решить, что делать.
//
// Модель отвечает одним из трёх: METKA:STEP:<роль> — водитель сообщил об
// этапе; METKA:ESCALATE — вопрос не по данным рейса; иначе — готовый
// ответ фактом из карточки.
//
// Роль в METKA:STEP нужна платформе: она сверит её со следующей
// непройденной точкой и откажет, если агент неверно понял фразу. Отметка
// — единственная запись во всём наборе, и цена ошибки здесь высокая.
//
// Модель: claude-opus-5. Для водителя за рулём важна скорость, поэтому
// effort low — задача простая, глубокое рассуждение ей не нужно.
// Если нужно дешевле — замените model на claude-haiku-4-5.

const trips = $json.trips;
const text = $('Подпись: контекст').item.json.text;

const system = [
  'Ты — диспетчер-помощник платформы RAHTIS для водителя грузовика.',
  'Водитель за рулём: отвечай КОРОТКО, одним-двумя предложениями.',
  '',
  'Отвечай ТОЛЬКО по данным рейсов ниже. Не выдумывай адреса, телефоны и время.',
  '',
  'Определи, что сделал водитель:',
  '1. СООБЩИЛ ОБ ЭТАПЕ (забрал, загрузился, выгрузился, сдал) — верни строго METKA:STEP:<роль>,',
  '   где роль одна из: PICKUP, DELIVERY, EXTRA_LOAD, EXTRA_UNLOAD, CONTINUATION, TRAILER_RETURN.',
  '   Роль бери из поля progress.next.role — водитель отмечает именно следующую точку.',
  '2. СПРОСИЛ по рейсу (где выгрузка, чей телефон, во сколько, нужна ли пломба) — ответь фактом.',
  '3. Вопрос вне данных рейса, спорный или про деньги и повреждения — верни строго METKA:ESCALATE.',
  '',
  'ВАЖНО про единицу: haul_kind = CONTAINER означает КОНТЕЙНЕР, а не прицеп.',
  'Тогда trailer_plate — это номер контейнера по ISO 6346, а container_feet — его длина в футах.',
  'Называй вещи своими именами: «контейнер 20 футов MSCU1234561», не «прицеп».',
  'При haul_kind = TRAILER это полуприцеп и его регистрационный номер.',
  '',
  'ПЛОЩАДКИ: в guides лежат инструкции по портам и терминалам этого рейса.',
  'Адрес ворот бери оттуда: он точнее адреса точки, если они разошлись.',
  'Часов работы и порядка въезда там нет — спросят про них, верни METKA:ESCALATE.',
  '',
  'Язык ответа — тот же, на котором написал водитель.',
  '',
  'ДАННЫЕ РЕЙСОВ:',
  JSON.stringify(trips),
].join('\n');

const payload = {
  model: 'claude-opus-5',
  max_tokens: 1024,
  output_config: { effort: 'low' },
  system,
  messages: [{ role: 'user', content: text }],
};

return [{ json: { payload: JSON.stringify(payload) } }];

// Достаём текст из ответа Claude.
//
// content — массив блоков разных типов. Берём только text: при
// включённом рассуждении там же приходят блоки thinking, и склеивать их
// в ответ водителю нельзя.

const blocks = Array.isArray($json.content) ? $json.content : [];
const reply = blocks.filter((b) => b.type === 'text').map((b) => b.text).join('').trim();

// Ошибка API приходит с полем error и без content.
if (!reply && $json.error) {
  return [{ json: { decision: 'ERROR', reply: 'Palvelu ei vastaa. / Служба не отвечает.', detail: $json.error?.message } }];
}

let decision = 'ANSWER';
let role = '';

if (reply.startsWith('METKA:STEP:')) {
  decision = 'STEP';
  role = reply.slice('METKA:STEP:'.length).trim().split(/\s/)[0];
} else if (reply.includes('METKA:ESCALATE')) {
  decision = 'ESCALATE';
}

return [{ json: { decision, role, reply } }];

// Подпись отметки этапа.
//
// expect — роль точки со слов водителя. Платформа сверит её со следующей
// непройденной точкой и откажет, если не совпало: агент, неверно понявший
// фразу, не должен продвигать рейс.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.DRIVER_WEBHOOK_SECRET) SECRET = $vars.DRIVER_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('DRIVER_WEBHOOK_SECRET ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v SECRET.');
const secret = SECRET;
const phone = $('Подпись: контекст').item.json.phone;

const body = JSON.stringify({ phone, expect: $json.role });
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');

return [{ json: { body, timestamp, signature } }];

// Подпись эскалации.
//
// Вопрос уходит в ту же очередь, которую оператор читает в админке.
// Работает независимо от того, есть ли у водителя активный рейс.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.DRIVER_WEBHOOK_SECRET) SECRET = $vars.DRIVER_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('DRIVER_WEBHOOK_SECRET ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v SECRET.');
const secret = SECRET;
const src = $('Проверить подпись провайдера').item.json;

const body = JSON.stringify({ phone: src.phone, question: src.text });
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');

return [{ json: { body, timestamp, signature } }];

// Что сказать водителю.
//
// Отказ платформы — штатный путь, а не исключение: «точка уже пройдена»,
// «роль не совпала», «рейс уже не идёт». Все три приходят кодом 55000 с
// понятным текстом в detail, и водителю надо показать именно его, а не
// общее «не получилось».

const src = $json;
let reply;

if (src.ok === true) {
  reply = 'Kuittaus vastaanotettu ✅ / Отметка принята ✅';
} else if (src.error) {
  // detail пишет та же функция базы, которая отказала: она знает почему.
  reply = src.detail || 'Ei onnistunut. / Не получилось.';
} else if (src.decision === 'ANSWER' || src.reply) {
  reply = src.reply;
} else {
  reply = 'Selvä. / Принято.';
}

return [{ json: { reply } }];

const src = $json;
const reply = src.ok === true
  ? 'Välitin kysymyksen ajojärjestelijälle. / Передал вопрос диспетчеру.'
  : (src.detail || 'Kysymystä ei saatu välitettyä. / Вопрос передать не удалось.');
return [{ json: { reply } }];

// Неверная подпись провайдера — тупик, и намеренно.
//
// Прежде эта ветка отвечала водителю текстом. С настоящей отправкой
// такой ответ означал бы, что любой, кто узнал адрес вебхука, может
// заставить наш номер написать произвольному человеку: подпись не
// сошлась, а номер взят из того же неподписанного тела.
//
// Мете при этом уже возвращён код 200 — узел вебхука отвечает сразу,
// не дожидаясь ветвления. Молчание здесь и есть правильный ответ.
//
// Причина видна в журнале выполнений n8n; наружу она не выходит, чтобы
// не подсказывать подбирающему, что именно не сошлось.
return [{ json: { refused: true } }];

// Подтверждение подписки на вебхук.
//
// Перед тем как слать события, Мета делает GET с hub.mode,
// hub.verify_token и hub.challenge и ждёт обратно значение challenge
// голым текстом. Без этого ответа подписку просто не создать — узел
// на POST для этого не годится, он на GET не отвечает.
//
// Токен здесь свой, не тот, которым подписываются сообщения: он
// нужен один раз при подключении и живёт отдельно, чтобы его можно
// было показать тому, кто настраивает, не отдавая App Secret.

// Значение берётся из переменных n8n ($vars — планы Pro и Enterprise
// Cloud): $env в узлах Code на облаке закрыт наглухо с версии 2.0.
//
// Если у вас Starter, где переменных нет, впишите значение в VALUE
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let VALUE = '';
try { if (typeof $vars !== 'undefined' && $vars.WHATSAPP_VERIFY_TOKEN) VALUE = $vars.WHATSAPP_VERIFY_TOKEN; } catch (e) {}
if (!VALUE) throw new Error('WHATSAPP_VERIFY_TOKEN ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v VALUE.');

const q = $json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === VALUE;

return [{ json: { ok, challenge: q['hub.challenge'] || '' } }];

// Сообщение водителю.
//
// Прежде ответ возвращался телом вебхука, и это не работало вовсе:
// Мете тело ответа не нужно, ей нужен код 200. Сообщение доходит
// только отдельным вызовом Graph API.
//
// Номер берётся из проверенного входящего, а не из тела запроса: на
// ветке с неверной подписью мы сюда не приходим вовсе, и наш номер
// нельзя заставить написать произвольному человеку.

// Значение берётся из переменных n8n ($vars — планы Pro и Enterprise
// Cloud): $env в узлах Code на облаке закрыт наглухо с версии 2.0.
//
// Если у вас Starter, где переменных нет, впишите значение в VALUE
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let VALUE = '';
try { if (typeof $vars !== 'undefined' && $vars.WHATSAPP_PHONE_ID) VALUE = $vars.WHATSAPP_PHONE_ID; } catch (e) {}
if (!VALUE) throw new Error('WHATSAPP_PHONE_ID ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v VALUE.');
const phoneId = VALUE;

const to = $('Проверить подпись провайдера').item.json.phone;
const reply = $json.reply;

return [{ json: { phoneId, to, reply } }];
